$('hunt').onclick=()=>{advance();if(!state.cls||state.mode==='city'||state.mode==='train'&&state.skill===100)return;state.active=!state.active;if(state.active&&!['train','gather'].includes(state.mode))ensureSession();progress=0;render();save();};$('heal').onclick=()=>{const s=stats();if(state.potions&&state.hp<s.h&&!state.rest&&state.mode!=='train'){state.potions--;if(state.active&&!['train','gather'].includes(state.mode))ensureSession().potionsUsed++;state.hp=Math.min(s.h,state.hp+Math.ceil(s.h*.5));render();save();}};
