for(const [id,[ico,label]] of Object.entries(WINDOW_DEFS)){const w=document.createElement('section');w.className='floating hidden';w.id='win-'+id;w.setAttribute('role','dialog');w.setAttribute('aria-label',label);w.innerHTML=`<header class="window-head"><h2>${ico} &nbsp;${label}</h2><button aria-label="Fechar ${label}" title="Fechar">×</button></header><div class="window-body" id="content-${id}"></div>`;layer.append(w);windows[id]=w;const head=w.querySelector('header');head.querySelector('button').onclick=()=>closeWindow(id);w.addEventListener('pointerdown',()=>focusWindow(id));head.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;e.preventDefault();keys.clear();head.setPointerCapture(e.pointerId);const r=w.getBoundingClientRect(),dx=e.clientX-r.left,dy=e.clientY-r.top;const move=ev=>{w.style.left=clamp(ev.clientX-dx,0,Math.max(0,innerWidth-w.offsetWidth))+'px';w.style.top=clamp(ev.clientY-dy,0,Math.max(0,innerHeight-w.offsetHeight))+'px';};const end=()=>{head.removeEventListener('pointermove',move);head.removeEventListener('pointerup',end);head.removeEventListener('pointercancel',end);rememberWindow(id);};head.addEventListener('pointermove',move);head.addEventListener('pointerup',end);head.addEventListener('pointercancel',end);});w.addEventListener('pointerup',()=>rememberWindow(id));}
for(const id of ['hero','zones','log','analyzer','records'])$('content-'+id).append(document.querySelector('[data-panel="'+id+'"]'));
for(const id of ['bag','equip','attr','talent','sub'])$('content-'+id).onclick=buildClick;
for(const mode of ['hunt','train','dungeon','boss'])$('content-'+mode).onclick=e=>{const b=e.target.closest('[data-select-mode]');if(b&&!b.disabled){switchActivity(mode);closeWindow(mode);}};
