const potion=$('buyPotion');$('content-hero').append(potion);potion.style.cssText='display:block;margin-top:12px;width:100%';
$('dockLeft').classList.add('hidden');$('dockRight').classList.add('hidden');$('activities').classList.add('hidden');$('hudSettings').remove();$('hudEdit').textContent='⚙ Configurações';$('hudEdit').onclick=()=>toggleWindow('settings');$('togglePanels').title='Fechar todas as janelas';$('togglePanels').setAttribute('aria-label','Fechar todas as janelas');
window.addEventListener('resize',()=>{for(const w of Object.values(windows))if(!w.classList.contains('hidden'))fitWindow(w);});window.addEventListener('keydown',e=>{if(e.key==='Escape'){const visible=Object.keys(windows).filter(id=>!windows[id].classList.contains('hidden')).sort((a,b)=>Number(windows[b].style.zIndex)-Number(windows[a].style.zIndex));if(visible.length)closeWindow(visible[0]);}});
