const QUALITY=['Gasta','Normal','Refinada','Obra-prima'];
function gearAttr(k,equipment=state.equipment){return Object.values(equipment).reduce((sum,id)=>sum+(state.inventory.find(x=>x.id===id)?.mods[k]||0),0);}
let bagFilter='all',selectedItem=null;let tooltip=null;
function itemIcon(it){const n=it.name.toLowerCase(),metal=['#b8b9c0','#a8d3aa','#8eb9e2','#c1a0f0','#efc86c'][it.rarity],dark='#564d4e';let shape='';if(it.slot==='offhand'&&/aljava/.test(n))shape=`<path d="M9 10h15l-3 19H12z" fill="#9a754b"/><path d="M10 13h13v4H10z" fill="${metal}"/><path d="M13 14V2m5 12V4m4 10V1" stroke="${metal}" stroke-width="2"/>`;else if(it.slot==='offhand'&&/orbe|relicário/.test(n))shape=`<path d="M6 11l5-7h10l5 7v10l-6 7h-8l-6-7z" fill="${metal}"/><path d="M11 12l5-5 5 5-5 9z" fill="#fff0cc"/><path d="M8 25h16v4H8z" fill="#a18251"/>`;else if(GEAR_SHAPES[it.slot])shape=GEAR_SHAPES[it.slot].replaceAll('@',metal);else if(it.slot==='armor')shape=`<path d="M8 4h5l3 4 3-4h5l6 7-5 6-3-3v14H10V14l-3 3-5-6z" fill="${metal}"/><path d="M13 8l3 4 3-4v16h-6z" fill="${dark}"/><path d="M10 24h12v3H10z" fill="#baa16d"/>`;else if(it.slot==='accessory')shape=`<path d="M8 8h16v4h4v13h-4v4H8v-4H4V12h4zM11 14v9h10v-9z" fill="#c49b54" fill-rule="evenodd"/><path d="M16 2l7 7-7 8-7-8z" fill="${metal}"/><path d="M16 4l-4 5 4 4z" fill="#fff6d9"/>`;else if(/arco|besta/.test(n))shape=`<path d="M6 3h5v3h5v4h4v12h-4v4h-5v3H6v-3h4v-4h4V10h-4V6H6z" fill="#b48553"/><path d="M6 3v26M4 16h24" stroke="${metal}" stroke-width="2"/><path d="M25 12l5 4-5 4z" fill="${metal}"/>`;else if(/cajado|cetro|grimório|grimorio/.test(n))shape=`<path d="M8 28L22 5" stroke="#9a754b" stroke-width="4"/><path d="M22 1l6 4v7l-6 4-6-4V5z" fill="${metal}"/><path d="M22 3l3 5-3 5-3-5z" fill="#fff5cf"/>`;else if(/machado|maça/.test(n))shape=`<path d="M8 28L23 5" stroke="#9c7147" stroke-width="4"/><path d="M15 4h13v12H17l-5-5z" fill="${metal}"/><path d="M25 4v12" stroke="#f6f0dd" stroke-width="2"/>`;else shape=`<path d="M5 27l5-5-3-3 2-2 5 5-2 2-5 5z" fill="#b08a4f"/><path d="M12 18L25 3l5-1-1 6-14 14z" fill="${metal}"/><path d="M15 17L27 5" stroke="#fff4d8" stroke-width="2"/><path d="M8 17l8 8" stroke="#d6a95e" stroke-width="3"/>`;return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" shape-rendering="crispEdges">${shape}</svg>`);}
function itemInfo(it){return `<b style="color:${RARITIES[it.rarity][1]}">${it.name}</b><div class="muted">${RARITIES[it.rarity][0]} · ${QUALITY[it.quality??1]} · ${SLOTS[it.slot]}</div><div style="margin:8px 0;color:#a9d7ad">${Object.entries(it.mods).map(([k,v])=>`+${v} ${modNames[k]||k}`).join('<br>')}</div><small>Região ${it.tier+1} · Venda: ${it.value} ◈${state.equipment[it.slot]===it.id?' · Equipado':''}</small>`;}
function attrTable(){const s=stats();return `<div class="sheet-title">Atributos fundamentais</div><p class="sheet-note">${spent(state.attrs)} pontos investidos de ${(state.level-1)*3} · ${attrPoints()} disponíveis</p><table class="sheet-table"><thead><tr><th>Atributo</th><th>Base</th><th>Alocado</th><th>Itens</th><th>Total</th><th>+</th></tr></thead><tbody>${Object.entries(ATTR).map(([k,[name,desc]])=>`<tr title="${desc}"><td>${name}<small class="attr-explain">${desc}</small></td><td>${C().base[k]}</td><td>+${state.attrs[k]}</td><td>+${gearAttr(k)}</td><td>${s.a[k]}</td><td><button class="secondary" data-attr="${k}" ${attrPoints()<=0?'disabled':''}>+</button></td></tr>`).join('')}</tbody></table>`;}
function renderSheet(){let el=$('sheetExtra');if(!el)return;const h=`${attrTable()}<p class="sheet-note">Os pontos alocados são recebidos ao subir de nível. Dano e vida também recebem bônus diretos de nível: +${(state.level*1.5).toFixed(1)} dano base, +${state.level*5} PV base e +${(state.level*.6).toFixed(1)} defesa, antes dos demais multiplicadores.</p>`+respec('attrs');if(el.innerHTML!==h)el.innerHTML=h;}
function renderRefined(t){let h='';if(t==='attr')h=attrTable()+`<p class="sheet-note">Os efeitos por ponto estão descritos na tabela; os multiplicadores e limites são aplicados ao combate.</p>`+respec('attrs');else if(t==='equip')h=gearPanel();else{const list=state.inventory.filter(i=>bagFilter==='all'||i.slot===bagFilter).sort((a,b)=>b.rarity-a.rarity||(b.quality??1)-(a.quality??1)||a.id-b.id),sel=state.inventory.find(i=>i.id===selectedItem);h=`<div class="bag-toolbar"><b>${state.inventory.length}/120 slots</b>${[['all','Todos'],...Object.entries(SLOTS)].map(([k,n])=>`<button class="secondary ${bagFilter===k?'active':''}" data-bagfilter="${k}">${n}</button>`).join('')}</div><div class="bag-grid">${Array.from({length:120},(_,i)=>{const it=list[i];return it?`<button class="bag-slot filled ${selectedItem===it.id?'selected':''}" style="--rar:${RARITIES[it.rarity][1]}" data-itemid="${it.id}" aria-label="${it.name} · ${RARITIES[it.rarity][0]} · ${QUALITY[it.quality??1]}"><img src="${itemIcon(it)}" alt=""><span class="qmark">${['I','II','III','IV'][it.quality??1]}</span>${state.equipment[it.slot]===it.id?'<span class="eqmark">E</span>':''}${socketDots(it)}</button>`:'<div class="bag-slot bag-empty" aria-hidden="true"></div>';}).join('')}</div><div class="bag-detail">${sel?itemInfo(sel)+(state.equipment[sel.slot]===sel.id?'':`<button class="secondary" data-equip="${sel.id}" ${canEquip(sel)?'':'disabled'}>Equipar</button><button class="secondary" data-sell="${sel.id}" ${state.mode==='city'?'':'disabled'}>Vender ${sel.value} ◈</button>`):'<span class="muted">Passe o mouse sobre um item. Venda disponível na cidade.</span>'}</div><p class="sheet-note">I Gasta · II Normal · III Refinada · IV Obra-prima. A cor indica a raridade; a qualidade modifica os atributos do item.</p>`;}const el=$('content-'+t);if(el&&el._markup!==h){el.innerHTML=h;el._markup=h;}}
const hudPaths={bestiary:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3Z M12 6v15 M5 8h4 M5 11h4 M15 8h4 M15 11h4',hero:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-3q0-5 8-5t8 5v3Z',bag:'M7 3h10l-2 5 5 6v7H4v-7l5-6Z M8 9h8',equip:'M4 20L19 5l1-3-3 1L5 15 M3 13l8 8 M3 21l4-4',attr:'M4 20V12h4v8 M10 20V8h4v12 M16 20V3h4v17',talent:'M12 2v6 M12 16v6 M2 12h6 M16 12h6 M12 8l4 4-4 4-4-4Z',sub:'M3 5l5 5 4-7 4 7 5-5-3 13H6Z M6 21h12',zones:'M3 5l6-3 6 3 6-3v17l-6 3-6-3-6 3Z M9 2v17 M15 5v17',hunt:'M3 3l17 17 M21 3L4 20 M3 17l4 4 M17 17l4 4',train:'M3 9h18 M5 5v14 M19 5v14 M2 8v8 M22 8v8',dungeon:'M4 22V9a8 8 0 0 1 16 0v13 M8 22V10a4 4 0 0 1 8 0v12 M2 22h20',boss:'M4 3l3 5h10l3-5v8l-3 5v4H7v-4l-3-5Z M8 12h2 M14 12h2 M10 17h4',analyzer:'M3 3v18h18 M6 16l5-6 4 3 6-8',log:'M5 3h14v18H5Z M8 7h8 M8 11h8 M8 15h8',records:'M7 3h10v7q0 5-5 5t-5-5Z M7 5H3v3q0 4 5 4 M17 5h4v3q0 4-5 4 M12 15v5 M7 21h10',settings:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12Z'};
function initRefinedHUD(){const extra=document.createElement('div');extra.id='sheetExtra';$('content-hero').insertBefore(extra,$('buyPotion'));extra.onclick=buildClick;tooltip=document.createElement('div');tooltip.className='itemtip hidden';document.body.append(tooltip);const bag=$('content-bag');bag.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.bagfilter){bagFilter=b.dataset.bagfilter;selectedItem=null;renderRefined('bag');}if(b.dataset.itemid){selectedItem=+b.dataset.itemid;renderRefined('bag');}if(b.dataset.sell||b.dataset.equip)tooltip.classList.add('hidden');});bag.addEventListener('pointermove',e=>{const b=e.target.closest('[data-itemid]'),it=b&&state.inventory.find(x=>x.id===+b.dataset.itemid);if(!it){tooltip.classList.add('hidden');return;}tooltip.innerHTML=itemInfo(it);tooltip.classList.remove('hidden');tooltip.style.left=Math.max(4,Math.min(e.clientX+14,innerWidth-tooltip.offsetWidth-6))+'px';tooltip.style.top=Math.max(4,Math.min(e.clientY+14,innerHeight-tooltip.offsetHeight-6))+'px';});bag.addEventListener('pointerleave',()=>tooltip.classList.add('hidden'));$('win-bag').querySelector('.window-head button').addEventListener('click',()=>tooltip.classList.add('hidden'));document.addEventListener('keydown',e=>{if(e.key==='Escape')tooltip.classList.add('hidden');});for(const [id,path] of Object.entries(hudPaths)){const ico=document.querySelector(`[data-window="${id}"] .navicon`);if(ico)ico.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${path}"/></svg>`;}}
let catchingUp=false;let target={x:470,y:330},targetSeed=0;const floaters=[];let fx=null;
function nextTarget(){if(state.mode!=='hunt'){target={x:470,y:330};return;}targetSeed++;const angle=targetSeed*2.39996;target={x:clamp(pos.x+Math.cos(angle)*65,290,535),y:clamp(pos.y+Math.sin(angle)*55,265,370)};}
function enemyPoint(now){return state.mode==='hunt'?{x:target.x+Math.sin(now/820+targetSeed)*9,y:target.y+Math.cos(now/1000+targetSeed)*6}:{x:470,y:330};}
function combatText(dmg,crit,special,incoming){const now=gameNow28(),p=incoming?pos:enemyPoint(now);floaters.push({x:p.x+(incoming?18:-18),y:p.y-45,t:now,text:incoming?(dmg?'-'+dmg:'ESQUIVA'):(crit?'CRÍT '+dmg:''+dmg),color:incoming?(dmg?'#ff777e':'#a8e1d3'):crit?'#ffd16b':special?'#b7a5ff':'#fff2d7',big:crit||special});if(!incoming)fx={x:p.x,y:p.y,fromX:pos.x,fromY:pos.y,t:now,special,cls:state.cls};}
function drawCombat(now){if(fx&&now-fx.t<480){const a=(now-fx.t)/480;ctx.save();ctx.globalAlpha=1-a;ctx.strokeStyle=fx.element12?ELEMENT12[fx.element12][1]:fx.special?({war:'#ffae68',ranger:'#a7e68a',mage:'#ae90ff',cleric:'#fff1a6'}[fx.cls]):'#e9d0a0';ctx.lineWidth=fx.special?3:2;ctx.beginPath();if(fx.cls==='war'){ctx.arc(fx.x,fx.y,15+a*8,-2.4,0.9);}else if(fx.cls==='ranger'){ctx.moveTo(fx.fromX+(fx.x-fx.fromX)*a,fx.fromY+(fx.y-fx.fromY)*a);ctx.lineTo(fx.x,fx.y);}else{ctx.arc(fx.x,fx.y,4+a*(fx.special?32:15),0,Math.PI*2);}ctx.stroke();if(fx.special){ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(state.lastSkill||C().special,fx.x,fx.y-47);}ctx.restore();}while(floaters.length&&now-floaters[0].t>1100)floaters.shift();for(const f of floaters){if(state.profile?.damage===false)continue;const a=Math.max(0,(now-f.t)/1100);ctx.save();ctx.globalAlpha=1-a*a;ctx.textAlign='center';ctx.font=`bold ${f.big?15:12}px monospace`;ctx.lineWidth=3;ctx.strokeStyle='#110d13';ctx.strokeText(f.text,f.x,f.y-a*28);ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y-a*28);ctx.restore();}}
function makeCrypt(){const floor=state.mode==='dungeon'?state.wave:4;for(let y=0;y<600;y+=20)for(let x=0;x<800;x+=24){const h=hash(x,y+floor*31);rect(bg,x,y,24,20,['#24242a','#2d2c32','#27282c'][h%3]);rect(bg,x,y,24,1,'#16171b');rect(bg,x,y,1,20,'#191a20');if(h%7===0)rect(bg,x+4,y+6,8,1,'#39383d');}for(let y=90;y<510;y+=24)for(let x=90;x<710;x+=26){if(x<160||x>640||y<140||y>460){rect(bg,x,y,25,22,'#39343a');rect(bg,x+1,y+1,23,4,'#51474a');}}for(const x of [270,530])for(const y of [230,400]){rect(bg,x-12,y-18,24,38,'#13141a');rect(bg,x-10,y-16,20,29,'#46404a');rect(bg,x-13,y-18,26,5,'#64565a');rect(bg,x-13,y+14,26,5,'#25232a');}const c=floor===4?'#68403a':'#43434c';rect(bg,340,287,160,72,c);rect(bg,346,293,148,60,'#24232a');for(let i=0;i<6;i++)rect(bg,355+i*24,298,12,4,c);for(const x of [310,490]){rect(bg,x,184,4,19,'#715d44');rect(bg,x-2,182,8,7,'#e39c58');rect(bg,x,178,4,8,'#ffdc91');}label(bg,420,211,floor===4?'CÂMARA DO CHEFE':'CRIPTA · ANDAR '+floor,'#c5ab87');}
function drawAtmosphere(now){if(state.mode==='hunt'){ctx.fillStyle='rgba(10,14,24,.23)';ctx.fillRect(0,0,800,600);for(let i=0;i<24;i++){const x=(hash(i,32)+now*.011*(1+i%3))%800,y=(hash(i,15)+Math.sin(now/2200+i)*15)%600;rect(ctx,x,y,1,1,'#c6b47b88');}}else if(state.mode!=='train'){for(const x of [312,492]){const g=ctx.createRadialGradient(x,185,2,x,185,55);g.addColorStop(0,'#ffaf5c44');g.addColorStop(1,'#ffaf5c00');ctx.fillStyle=g;ctx.fillRect(x-55,130,110,110);}}}


const GEAR_SHAPES={head:'<path d="M9 3h14l5 7v12h-6v6H10v-6H4V10z" fill="@"/><path d="M7 13h18v5H7zM14 18h4v10h-4z" fill="#34313a"/><path d="M13 3h4v10h-4z" fill="#eee5d1"/>',offhand:'<path d="M5 4h22v16l-11 10L5 20z" fill="@"/><path d="M8 7h16v12l-8 8-8-8z" fill="#55464a"/><path d="M14 8h4v16h-4zM9 13h14v4H9z" fill="@"/>',hands:'<path d="M4 4h5v11h3V8h4v9l-3 12H4L1 17zM20 4h5v11h3V8h3v9l-3 12h-9l-3-12z" fill="@"/><path d="M4 22h9v4H4zM19 22h9v4h-9z" fill="#826b4b"/>',legs:'<path d="M6 3h20v11l-3 15h-7V15h-1v14H7L5 14z" fill="@"/><path d="M6 6h20v4H6zM8 17h5v3H8zM19 17h5v3h-5z" fill="#635147"/>',feet:'<path d="M4 3h10v18l4 4v4H2v-5l2-5zM19 3h10v18l2 4v4H18v-5l1-5z" fill="@"/><path d="M4 10h10v3H4zM19 10h10v3H19zM2 27h16v2H2zM18 27h13v2H18z" fill="#665248"/>',ring:'<path d="M8 9h16v4h4v12h-4v4H8v-4H4V13h4zM11 15v8h10v-8z" fill="#b99b5c" fill-rule="evenodd"/><path d="M11 3h10l3 6-8 7-8-7z" fill="@"/><path d="M12 5h5l-4 6z" fill="#fff2cf"/>'};
let gearSelected='weapon';
const gearDescriptions={head:'Proteção da cabeça e resistência.',accessory:'Amuleto que aprimora o poder do portador.',weapon:'Principal fonte de dano da vocação.',offhand:'Equipamento auxiliar de combate.',armor:'Proteção do torso e sobrevivência.',hands:'Precisão e força dos ataques.',legs:'Proteção das pernas.',ring:'Bônus de combate e proficiência.',feet:'Proteção e destreza.'};
function gearPanel(){const eq=state.equipment,sel=state.inventory.find(i=>i.id===eq[gearSelected]),s=stats(),base=stats({});const total=Object.keys(SLOTS).filter(k=>state.inventory.some(i=>i.id===eq[k])).length;const slot=k=>{const it=state.inventory.find(i=>i.id===eq[k]);return `<button class="gear-cell ${gearSelected===k?'chosen':''} ${it?'occupied':''}" data-gearslot="${k}" ${it?`data-gearitem="${it.id}"`:''} style="--slotrar:${it?RARITIES[it.rarity][1]:'#615748'}" aria-label="${SLOTS[k]}: ${it?it.name:'Vazio'}"><span class="gear-pic"><img src="${itemIcon(it||{name:k==='weapon'?C().weapon[0]:SLOTS[k],slot:k,rarity:0})}" alt="">${it?`<span class="qmark">${['I','II','III','IV'][it.quality??1]}</span>${socketDots(it)}`:''}</span><span class="gear-slotname">${SLOTS[k]}</span><span class="gear-itemname">${it?it.name:'Vazio'}</span></button>`;};const portrait=`<div class="gear-portrait"><div class="gear-halo"></div><svg viewBox="0 0 80 124" aria-label="Representação da vocação" shape-rendering="crispEdges"><path d="M16 120h48v3H16z" fill="#090a0d"/><path d="M24 70h13v41H22v-12h2zM43 70h13v29h2v12H43z" fill="#55515a"/><path d="M20 107h17v12H16v-6zM43 107h17l4 6v6H43z" fill="#302b30"/><path d="M18 42l22-8 22 8 5 23-12 8-4 10H29l-4-10-12-8z" fill="${C().color}"/><path d="M31 42h18v31H31z" fill="#43434d"/><path d="M26 70h28v6H26z" fill="#ad8e56"/><path d="M28 15h24l8 12v17H20V27z" fill="#8b8c90"/><path d="M25 28h30v7H25z" fill="#24252c"/><path d="M34 35h12v8H34z" fill="#b5a28a"/><path d="M17 51h8v29h-8zM55 51h8v29h-8z" fill="#b29d82"/><path d="M65 26h4v48h-4zM60 69h14v4H60z" fill="#b9a87c"/></svg><strong>${title()}</strong><small>Nível ${state.level}</small></div>`;const rows=[['Dano',s.dmg,base.dmg,''],['Defesa',s.def,base.def,''],['Vida máxima',s.h,base.h,''],['Chance crítica',s.crit*100,base.crit*100,'%'],['Esquiva',s.dodge*100,base.dodge*100,'%'],['Multiplicador de habilidade',s.special,base.special,'×'],['Força',s.a.str,base.a.str,''],['Destreza',s.a.dex,base.a.dex,''],['Inteligência',s.a.int,base.a.int,''],['Sabedoria',s.a.wis,base.a.wis,''],['Vitalidade',s.a.vit,base.a.vit,''],['Proficiência para dano',state.skill+gearAttr('skill'),state.skill,'']];const num=n=>Number(n.toFixed(2)).toLocaleString('pt-BR');return `<div class="gear-top"><span class="eyebrow">Conjunto equipado</span><b>${total}/9 slots</b></div><div class="gear-paper"><div class="gear-col">${['head','weapon','armor','legs'].map(slot).join('')}</div><div class="gear-mid">${portrait}${slot('feet')}</div><div class="gear-col">${['accessory','offhand','hands','ring'].map(slot).join('')}</div></div><div class="gear-inspect"><div class="eyebrow">${SLOTS[gearSelected]}</div>${sel?itemInfo(sel)+'<p class="muted">'+gearDescriptions[gearSelected]+'</p>':'<b>Slot vazio</b><p class="muted">'+gearDescriptions[gearSelected]+'</p>'}<div class="gear-actions"><button class="secondary" data-gearbag="${gearSelected}">${sel?'Trocar equipamento':'Buscar no inventário'}</button>${sel?`<button class="secondary" data-unequip="${gearSelected}">Desequipar</button>`:''}</div></div><h3 class="gear-heading">Efeitos do conjunto</h3><div class="rune-line">${setCounts().map((n,i)=>n?SET_NAMES[i]+' '+n+'/3'+(n>=3?' · ativo':''):'').filter(Boolean).join('<br>')||'Nenhum conjunto equipado.'}${RELICS.map((r,i)=>equippedRelic(i)?'<br>'+r.effect:'').join('')}</div><p class="sheet-note">Comparação com o mesmo personagem sem equipamentos, incluindo talentos e subclasse. Valores efetivos após limites.</p><table class="sheet-table gear-summary"><thead><tr><th>Estatística</th><th>Sem itens</th><th>Bônus</th><th>Total</th></tr></thead><tbody>${rows.map(([n,a,b,u])=>`<tr><td>${n}</td><td>${num(b)}${u}</td><td class="${a-b>0.00001?'gear-positive':'muted'}">+${num(Math.max(0,a-b))}${u==='%'?' p.p.':u}</td><td>${num(a)}${u}</td></tr>`).join('')}</tbody></table>`;}
function initGearHUD(){const el=$('content-equip');el.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.gearslot){gearSelected=b.dataset.gearslot;renderRefined('equip');}if(b.dataset.gearbag){bagFilter=b.dataset.gearbag;selectedItem=null;openWindow('bag');renderRefined('bag');}tooltip.classList.add('hidden');});el.addEventListener('pointermove',e=>{const b=e.target.closest('[data-gearitem]'),it=b&&state.inventory.find(i=>i.id===+b.dataset.gearitem);if(!it){tooltip.classList.add('hidden');return;}tooltip.innerHTML=itemInfo(it);tooltip.classList.remove('hidden');tooltip.style.left=Math.max(4,Math.min(e.clientX+14,innerWidth-tooltip.offsetWidth-6))+'px';tooltip.style.top=Math.max(4,Math.min(e.clientY+14,innerHeight-tooltip.offsetHeight-6))+'px';});el.addEventListener('pointerleave',()=>tooltip.classList.add('hidden'));}


// Eldoria 0.8 — Vespera, relics, socketing and the regional atlas.
const RELICS=[{name:'Coração da Floresta Morta',slot:'accessory',hp:250,atk:21,mods:{vit:12,hp:85,def:8},effect:'Raízes ancestrais: +12% vida máxima e 8% redução de dano.'},{name:'Lâmina do Rei Sepulcral',slot:'weapon',hp:480,atk:39,mods:{damage:36,str:8,dex:8,crit:6},effect:'Execução sepulcral: +35% dano contra inimigos abaixo de 30% de PV.'},{name:'Selo do Dragão de Cinza',slot:'ring',hp:1050,atk:67,mods:{damage:18,int:10,crit:10,skill:8},effect:'Sangue dracônico: +20% dano de habilidade e +10% dano básico.'}];
const RUNES={might:{name:'Runa da Fúria',mods:{damage:6},price:120,desc:'+6 dano base'},guard:{name:'Runa da Égide',mods:{def:5,hp:20},price:120,desc:'+5 defesa, +20 PV'},focus:{name:'Runa da Precisão',mods:{crit:3},price:150,desc:'+3 p.p. de crítico'},arcane:{name:'Runa Arcana',mods:{int:4,skill:3},price:150,desc:'+4 inteligência, +3 proficiência efetiva'}};
const PRICE=[1,2,5,12,35], CITYNPC=[{x:305,y:250,name:'Bram · Ferreiro',mode:'forge'},{x:495,y:250,name:'Mira · Mercadora',mode:'merchant'},{x:305,y:390,name:'Instrutor',mode:'train'},{x:495,y:390,name:'Cartógrafo',mode:'zones'},{x:400,y:190,name:'Mestre de provas',mode:'sub'}];
function currentNPCs(){return state.mode==='city'?CITYNPC:[];}
function normalizeItem(it){if(!it.baseMods)it.baseMods={...it.mods};if(!Number.isInteger(it.upgrade))it.upgrade=0;if(!Array.isArray(it.runes))it.runes=[];if(!it.relic&&it.relic!==0)it.relic=null;if(it.setId===undefined)it.setId=it.relic===null&&it.rarity>=2&&['head','armor','legs','hands','feet'].includes(it.slot)?it.tier:null;return it;}
function sockets(it){return it.relic!==null?3:it.rarity>=4?2:it.rarity>=2?1:0;}
function rebuildItem(it){normalizeItem(it);it.mods=Object.fromEntries(Object.entries(it.baseMods).map(([k,v])=>[k,Math.max(1,Math.round(v*(1+.1*it.upgrade)))]));for(const key of it.runes){for(const [k,v] of Object.entries(RUNES[key]?.mods||{}))it.mods[k]=(it.mods[k]||0)+v;}it.value=Math.round((6+it.tier*8)*PRICE[it.rarity]*(1+.1*(it.quality??1))*(it.relic!==null?6:1));return it;}
function normalizeWorld(){if(!Number.isFinite(state.attrs.wis)){state.attrs.wis=state.cls==='cleric'?(state.attrs.int||0):0;if(state.cls==='cleric'){state.attrs.int=0;for(const it of state.inventory){if(it.vocation&&it.vocation!=='cleric')continue;for(const m of [it.baseMods,it.mods]){if(m&&m.int){m.wis=(m.wis||0)+m.int;delete m.int;}}}}}state.runeStock={might:0,guard:0,focus:0,arcane:0,...state.runeStock};for(const it of state.inventory)rebuildItem(it);}
const oldFresh=fresh;fresh=function(cls=null){return {...oldFresh(cls),runeStock:{might:0,guard:0,focus:0,arcane:0}}};
const oldItem=item;item=function(...args){return rebuildItem(oldItem(...args));};
function equippedRelic(i,equipment=state.equipment){return Object.values(equipment).some(id=>state.inventory.some(it=>it.id===id&&it.relic===i));}
const SET_NAMES=['Vigília do Bosque','Juramento de Valdren','Legião de Cinza'];function setCounts(equipment=state.equipment){const counts=Array(ZONES.length).fill(0);for(const id of Object.values(equipment)){const it=state.inventory.find(x=>x.id===id);if(it&&normalizeItem(it).setId!==null)counts[it.setId]++;}return counts;}const oldStats=stats;stats=function(equipment=state.equipment){const a=oldStats(equipment),sets=setCounts(equipment);if(sets[0]>=3)a.h=Math.floor(a.h*1.10);if(sets[1]>=3)a.def+=10;if(sets[2]>=3)a.dmg*=1.12;if(equippedRelic(0,equipment)){a.h=Math.floor(a.h*1.12);a.reduction=Math.min(.85,a.reduction+.08);}if(equippedRelic(2,equipment)){a.dmg*=1.1;a.special*=1.2;}return a;};
function relicStrike(e){return equippedRelic(1)&&state.enemyHp/e.hp<.30?1.35:1;}
function bossReward(){if(Math.random()<.18){const k=rand(Object.keys(RUNES));state.runeStock[k]=(state.runeStock[k]||0)+1;log('Runa encontrada: '+RUNES[k].name,'rare');}if(Math.random()>=.0025||state.inventory.length>=120)return;const r=RELICS[state.zone],it=rebuildItem({id:state.nextId++,name:r.name,slot:r.slot,rarity:4,tier:state.zone,quality:3,baseMods:relicMods10(r),mods:relicMods10(r),upgrade:0,runes:[],relic:state.zone});state.inventory.push(it);state.drops++;recordDrop(it);log('RELÍQUIA EXCLUSIVA: '+it.name+'!','rare');}
const oldItemInfo=itemInfo;itemInfo=function(it){normalizeItem(it);return oldItemInfo(it)+`<div class="rune-line">Aprimoramento +${it.upgrade}/10 · Runas ${it.runes.length}/${sockets(it)}</div>${it.relic!==null?`<div class="relic-line">✦ Relíquia exclusiva<br>${RELICS[it.relic].effect}</div>`:''}${it.setId!==null?`<div class="rune-line">Conjunto ${SET_NAMES[it.setId]} · ${setCounts()[it.setId]}/3 peças equipadas<br>3 peças: ${SET_EFFECT16[it.setId]}</div>`:''}${comparison(it)}`;};
function comparison(it){const eq=state.inventory.find(x=>x.id===state.equipment[it.slot]);if(!eq||eq.id===it.id)return '';const a=stats(),b=stats({...state.equipment,[it.slot]:it.id});const deltas=[['Dano',b.dmg-a.dmg],['Defesa',b.def-a.def],['PV',b.h-a.h],['Crítico (p.p.)',(b.crit-a.crit)*100]].map(([k,v])=>`<span style="color:${v<0?'#e38d84':v>0?'#a9d7ad':'#aaa'}">${k}: ${v>=0?'+':''}${Number(v.toFixed(2))}</span>`);return `<div class="rune-line">Comparado ao equipado (${eq.name}):<br>${deltas.join(' · ')}</div>`;}
