const oldMap=makeMap;makeMap=function(){if(state.mode==='city'){paintCity();return;}oldMap();if(state.mode!=='hunt')return;for(let i=0;i<70;i++){const x=20+hash(i,42)%760,y=20+hash(i,59)%560;if(Math.abs(x-400)<100||Math.abs(y-320)<45||NPCS.some(n=>Math.hypot(x-n.x,y-n.y)<45))continue;if(state.zone===0){rect(bg,x,y,4,2,'#719071');rect(bg,x+2,y-3,2,5,'#384f37');if(i%5===0)rect(bg,x,y-4,2,2,'#b4a17b');}else if(state.zone===1){rect(bg,x,y,15,8,'#37383d');rect(bg,x+2,y-3,10,4,'#88817a');rect(bg,x+3,y+1,9,1,'#aaa28d');}else{rect(bg,x,y,14,5,'#382b2c');rect(bg,x+3,y+1,9,1,'#ae5b39');}}};
function mapThumb(){const c=document.createElement('canvas');c.width=320;c.height=240;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(mapBg,0,0,320,240);return c.toDataURL();}let previews=null;function thumbnails(){if(previews)return previews;const old={zone:state.zone,mode:state.mode};previews=[];for(let i=0;i<ZONES.length;i++){state.zone=i;state.mode='hunt';makeMap();previews.push(mapThumb());}state.mode='city';makeMap();previews.push(mapThumb());Object.assign(state,old);makeMap();return previews;}
const ZDESC=['Bosque úmido e esquecido, tomado por criaturas corrompidas.','Vestígios de uma fortaleza sepultada; mortos-vivos guardam seus corredores.','Picos vulcânicos e fendas incandescentes sob o domínio de um dragão ancestral.'];
function regionPanel(){const pics=thumbnails();return `<div class="region-card"><img src="${pics[ZONES.length]}"><div><h3>Vespera</h3><p>Cidade principal · Zona segura</p><p class="muted">Ferreiro, mercadora, cartógrafo e mestre de ofícios.</p><button class="secondary" data-city-go>Viajar à cidade</button></div></div>`+ZONES.map((z,i)=>`<div class="region-card"><img src="${pics[i]}" alt="Mapa de ${z.name}"><div><h3>${z.name}</h3><p>Nível recomendado: ${z.level}+ · Dungeon ${Math.max(3,z.level+2)}+ · Boss ${Math.max(5,z.level+4)}+</p><p>${ZDESC[i]}</p><p class="muted">Inimigos: ${z.enemy.map(k=>ENEMIES[k].name).join(', ')}</p><p class="muted">Loot: armas da vocação, armaduras e acessórios ${['do Bosque','de Valdren','de Cinza'][i]}; comum a lendário.</p><p style="color:#e5bf77">Boss: ${BOSSES[i]} · ${RELICS[i].name} (0,25% por vitória no chefe)</p><button class="secondary" data-travel="${i}" ${state.level<z.level?'disabled':''}>${state.level<z.level?'Bloqueado':'Viajar'}</button></div></div>`).join('');}
function cityPanel(){return `<div class="service-card"><h3>Vespera, a cidadela crepuscular</h3><p>Zona segura. Viaje até a cidade e converse com os NPCs usando E.</p><button class="primary" data-city-go>${atCity()?'Voltar ao mapa':'Viajar à cidade'}</button></div><div class="town-npcs">${CITYNPC.map(n=>`<button class="secondary" data-city-service="${n.mode}" ${atCity()?'':'disabled'}>${n.name}</button>`).join('')}</div>`;}
function forgePanel(){const it=selectedForge();if(it)normalizeItem(it);return `<div class="service-card"><h3>Forja de Bram</h3><p>+10% dos atributos originais por nível, até +10. Sucesso garantido. O valor de revenda não aumenta.</p><p>Ouro: ${fmt(state.gold)} ◈ · ${atCity()?'Serviço disponível':'Viaje a Vespera para utilizar.'}</p>${it?`<select id="forgePick">${state.inventory.map(x=>`<option value="${x.id}" ${x.id===it.id?'selected':''}>${x.name} +${x.upgrade||0} · ${RARITIES[x.rarity][0]}</option>`).join('')}</select><div class="service-card">${itemInfo(it)}<br><button class="primary" data-upgrade ${!atCity()||it.upgrade>=10||state.gold<forgeCost(it)?'disabled':''}>${it.upgrade>=10?'Nível máximo':'Aprimorar · '+forgeCost(it)+' ◈'}</button></div><h3>Encaixes de runas</h3><p>${it.runes.length}/${sockets(it)} ocupados. Inserção: 25 ouro. Remoção destrói a runa.</p>${Object.entries(RUNES).filter(([k,r])=>!r.slot||r.slot===it.slot).map(([k,r])=>`<div>${r.name} (${state.runeStock[k]||0}) · ${r.desc}<br><button class="secondary" data-socket="${k}" ${!atCity()||!state.runeStock[k]||it.runes.length>=sockets(it)||state.gold<25?'disabled':''}>Inserir</button></div>`).join('')}${it.runes.map((k,i)=>`<button class="secondary" data-remove-rune="${i}" ${atCity()?'':'disabled'}>Remover ${RUNES[k].name}</button>`).join('')}`:'<p>Sem equipamentos.</p>'}</div>`;}
function merchantPanel(){return `<div class="service-card"><h3>Mercado de Mira</h3><p>Ouro: ${fmt(state.gold)} ◈ · ${atCity()?'Comércio disponível':'Viaje a Vespera para negociar.'}</p><button class="secondary" data-buy-potion ${!atCity()||state.gold<POTION_VALUE?'disabled':''}>Poção · ${POTION_VALUE} ◈</button>${Object.entries(RUNES).map(([k,r])=>`<div>${r.name} · ${r.desc} (${state.runeStock[k]||0}) <button class="secondary" data-buy-rune="${k}" ${!atCity()||state.gold<r.price?'disabled':''}>${r.price} ◈</button></div>`).join('')}</div><h3>Vender equipamentos</h3><p class="muted">Itens equipados ficam protegidos. Preço por raridade e região.</p><div class="merchant-list">${state.inventory.filter(it=>!Object.values(state.equipment).includes(it.id)).map(it=>`<div class="merchant-row"><img src="${itemIcon(it)}"><span style="color:${RARITIES[it.rarity][1]}">${it.name} +${it.upgrade||0}</span><button class="secondary" data-sell="${it.id}" ${atCity()?'':'disabled'}>${it.value} ◈</button></div>`).join('')||'<p>Nenhum item disponível.</p>'}</div>`;}
const oldRefresh=refreshWindows;refreshWindows=function(){oldRefresh();if(!state.cls)return;for(const [id,fn] of Object.entries({zones:regionPanel,city:cityPanel,forge:forgePanel,merchant:merchantPanel})){if(windows[id]&&!windows[id].classList.contains('hidden')){const el=id==='zones'?$('zones'):$('content-'+id),h=fn();if(el.innerHTML!==h)el.innerHTML=h;}}};
const oldRender=render;render=function(){oldRender();if(!state.cls)return;$('buyPotion').disabled=!atCity()||state.gold<POTION_VALUE;const labels={'Dano médio':'Dano de ataque antes do crítico e da defesa inimiga.','Defesa':'A armadura reduz uma fração do ataque inimigo, com retorno decrescente e limite de 56%.','Vida máxima':'Quanto maior, mais dano pode suportar.','Crítico':'Chance de aplicar multiplicador de dano crítico (máx. 85%).','Esquiva':'Chance de evitar o ataque recebido (máx. 60%).','Habilidade':'Ataque especial da vocação.','Poder da habilidade':'Multiplica o dano do ataque especial.'};for(const el of $('stats').children){const key=el.firstChild?.textContent;if(labels[key]){const small=document.createElement('small');small.className='attr-explain';small.textContent=labels[key];el.append(small);}}};
const oldChoose=choose;choose=function(cls){oldChoose(cls);normalizeWorld();switchActivity('city',0);};
function initWorld(){for(const id of ['zones','city','forge','merchant'])$('content-'+id).addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.cityGo!==undefined){switchActivity('city',state.zone);closeWindow(id);return;}if(d.travel!==undefined){switchActivity('hunt',+d.travel);closeWindow(id);return;}if(d.cityService&&atCity()){if(d.cityService==='train'){switchActivity('train');closeWindow(id);}else openWindow(d.cityService);return;}if(!atCity())return;const it=selectedForge();if(d.upgrade!==undefined&&doUpgrade(it))log('Aprimoramento +'+it.upgrade,'rare');if(d.socket&&doSocket(it,d.socket))log('Runa inserida.','rare');if(d.removeRune!==undefined&&it?.runes[+d.removeRune]&&confirm('Destruir esta runa?')){it.runes.splice(+d.removeRune,1);rebuildItem(it);}if(d.buyPotion!==undefined&&state.gold>=POTION_VALUE){state.gold-=POTION_VALUE;state.consumables.hp1=(state.consumables.hp1||0)+1;}if(d.sell){buildClick(e);return;}state.hp=Math.min(state.hp,stats().h);render();save();});$('content-forge').addEventListener('change',e=>{if(e.target.id==='forgePick'){forgeId=+e.target.value;refreshWindows();}});$('buyPotion').onclick=()=>{if(atCity()&&state.gold>=POTION_VALUE){state.gold-=POTION_VALUE;state.potions++;render();save();}};for(const [k,p] of Object.entries({city:'M3 21V5h5v5h8V5h5v16 M9 21v-6h6v6',forge:'M3 7h18l-4 5h-5v5l4 4H5l4-4v-5H6Z',merchant:'M12 2v20 M17 6H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6'})){hudPaths[k]=p;}}

