const n09=nodes;nodes=function(){return n09().map((branch,i)=>{const n=branch.map(x=>({...x}));if(i===2)n[2].desc='Maestria: -1 s de cooldown de todas as habilidades (mín. 2 s).';const k=SKILLS[state.cls][i];return [...n.slice(0,2),{id:k[0],name:k[1],icon:k[2],desc:'Habilidade ativa automática · '+k[3]+' mana · '+k[4]+' s de recarga base',max:3,pre:n[1].id,level:5,active:true},n[2],{id:['p','q','r'][i],name:['Potência aprimorada','Reserva interior','Fluxo acelerado'][i],icon:['✷','◈','⌛'][i],desc:['+6% dano de habilidade por ponto','+8 mana máxima e +0,4 mana/s por ponto','-1 s recarga de habilidades por ponto (mín. 2 s)'][i],max:3,pre:k[0],level:8},{id:['u','v','w'][i],name:['Domínio ofensivo','Vigor ancestral','Precisão superior'][i],icon:['⚔','♥','◎'][i],desc:['+5% dano total por ponto','+5% PV máximo por ponto','+3 p.p. dano crítico por ponto'][i],max:3,pre:['p','q','r'][i],level:12}];});};
function nodeAvailable(n){return state.level>=(n.level||1)&&(!n.pre||rank(n.pre)>=2);}
const s09=stats;stats=function(equipment=state.equipment){const s=s09(equipment);s.dmg*=1+.05*rank('u');s.h=Math.floor(s.h*(1+.05*rank('v')));s.special*=1+.06*rank('p');s.critMult+=.03*rank('w');s.reduction=Math.min(.85,s.reduction);s.mana=Math.floor(30+state.level*3+(s.a.int+(state.cls==='cleric'?s.a.wis:0))*4+rank('q')*8);s.manaRegen=1+s.a.int*.08+s.a.wis*.12+rank('q')*.4;return s;};
function skillData(k){const [id,name,icon,mana,cd,power,heal,guard]=k;return {id,name,icon,mana,cd:Math.max(2,cd-rank('i')-rank('r')-(state.cls==='mage'&&state.subclass===2?1:0)),power:power*(1+.18*Math.max(0,rank(id)-1)),heal:heal*(1+.15*Math.max(0,rank(id)-1))*(state.cls==='cleric'&&state.subclass===2?1.8:1),guard};}
function ensureResources(){if(!state.cls)return;const s=stats();if(!Number.isFinite(state.mana))state.mana=s.mana;state.mana=clamp(state.mana,0,s.mana);state.cooldowns=state.cooldowns||{};state.guardTurns=state.guardTurns||0;}
function tickResources(){ensureResources();const s=stats();state.mana=Math.min(s.mana,state.mana+s.manaRegen);for(const k of Object.keys(state.cooldowns))state.cooldowns[k]=Math.max(0,state.cooldowns[k]-1);state.guardTurns=Math.max(0,state.guardTurns-1);}
function castSkill(s){ensureResources();const unlocked=SKILLS[state.cls].filter(k=>rank(k[0])>0).map(skillData);const k=unlocked.find(k=>!(state.cooldowns[k.id]>0)&&state.mana>=k.mana);if(!k)return null;state.mana-=k.mana;state.cooldowns[k.id]=k.cd;state.lastSkill=k.name;return k;}
const spawn09=spawn;spawn=function(){spawn09();};
const norm09=normalizeItem;normalizeItem=function(it){norm09(it);if(!Number.isInteger(it.socketCount)){const odds=SOCKET_ODDS[it.relic!==null?5:it.rarity];let roll=Math.random()*100,chosen=0;for(let i=0;i<4;i++){roll-=odds[i];if(roll<0){chosen=i;break;}}it.socketCount=Math.max(chosen,it.runes.length);}return it;};
sockets=function(it){return normalizeItem(it).socketCount;};
const rebuild09=rebuildItem;rebuildItem=function(it){rebuild09(it);it.value=Math.round(it.value*(1+.2*sockets(it)));return it;};
function reqItem(it){normalizeItem(it);const starter=it.name.includes('de aprendiz');const level=starter?1:it.relic!==null?Math.max(5,ZONES[it.tier].level+4):ZONES[it.tier].level+Math.max(0,it.rarity-2);const key=SLOT_REQ[it.slot]||C().main;const value=starter?0:Math.max(0,2+it.tier*3+it.rarity*2+(it.relic!==null?3:0));return {level,key,value};}
function canEquip(it){const r=reqItem(it);return state.level>=r.level&&C().base[r.key]+state.attrs[r.key]>=r.value;}
