function deepStats(){const s=stats(),base=stats({});const rows=[['Dano básico',s.dmg,base.dmg,'','Dano antes de crítico, execução e variação aleatória.'],['Defesa',s.def,base.def,'','Cada ponto subtrai 1 do ataque inimigo antes da redução.'],['Vida máxima',s.h,base.h,'','Capacidade total de suportar dano.'],['Mana máxima',s.mana,base.mana,'','Reserva de recurso consumido por habilidades.'],['Regeneração de mana',s.manaRegen,base.manaRegen,'/s','Recuperação por segundo de atividade.'],['Chance crítica',s.crit*100,base.crit*100,'%','Chance de dano crítico, limitada a 58%.'],['Dano crítico',s.critMult,base.critMult,'×','Multiplica o dano quando crítico.'],['Esquiva',s.dodge*100,base.dodge*100,'%','Chance de evitar o ataque, limitada a 23% (30% para Arqueiro).'],['Redução de dano',s.reduction*100,base.reduction*100,'%','Reduz o dano após a defesa, máximo 52%.'],['Poder da habilidade',s.special,base.special,'×','Multiplicador antes do poder específico da skill.'],['Proficiência',state.skill+gearAttr('skill'),state.skill,'','Cada nível acima do primeiro aumenta o multiplicador de dano em 0,9%.']];const f=x=>Number(x.toFixed(2)).toLocaleString('pt-BR');return `<h3 class="sheet-title">Estatísticas efetivas</h3><p class="sheet-note">Sem itens inclui pontos, nível, talentos e subclasse. O bônus é a diferença efetiva com os itens equipados, incluindo conjuntos e runas.</p><table class="sheet-table"><thead><tr><th>Estatística</th><th>Sem itens</th><th>Itens</th><th>Total</th></tr></thead><tbody>${rows.map(([n,a,b,u,d])=>`<tr><td>${n}<small class="attr-explain">${d}</small></td><td>${f(b)}${u}</td><td class="gear-positive">${a-b>=0?'+':''}${f(a-b)}${u==='%'?' p.p.':u}</td><td>${f(a)}${u}</td></tr>`).join('')}</tbody></table><p class="sheet-note">Bônus diretos do nível: +${f(state.level*1.5)} dano, +${state.level*5} PV, +${f(state.level*.6)} defesa e +${state.level*3} mana, antes dos multiplicadores.</p>`;}
