function statusState(){return state.effects||(state.effects={hero:{},enemy:{},clock:{hero:1,enemy:1},immunity:0});}
function hasStatus(side,k){return !!statusState()[side][k];}
function bossArena(){return state.mode==='boss'||state.mode==='trial'||state.mode==='dungeon'&&state.wave===4;}
function applyStatus(side,k,power){const a=statusState(),d=EFFECTS[k];if(!d)return false;const control=k==='stun'||k==='freeze';if(side==='enemy'&&control&&bossArena()&&a.immunity>0)return false;const old=a[side][k],duration=side==='enemy'&&control&&bossArena()?1:d[3];a[side][k]={left:duration,power:Math.max(power,old?.power||0),stacks:k==='poison'?Math.min(3,(old?.stacks||0)+1):1};if(side==='enemy'&&control&&bossArena())a.immunity=6;statusText(side,d[0],d[2]);return true;}
function statusText(side,text,color){if(suppress||document.hidden)return;const p=side==='hero'?pos:enemyPoint(gameNow28());floaters.push({x:p.x,y:p.y-64,t:gameNow28(),text,color,big:false});}
function applySkillStatus(k,dmg){for(const e of SKILL_EFFECTS[state.cls][k.id]||[])applyStatus('enemy',e,dmg);}
function enemyStatus(e){if(Math.random()<.45)applyStatus('hero',bossArena()?['bleed','expose','burn','poison','freeze','expose','stun','burn','shock','slow'][state.zone]:ENEMIES[state.enemy].effect,e.atk);}
function statusDamage(from,to){return (hasStatus(from,'shock')?.8:1)*(hasStatus(to,'expose')?1.2:1);}
function attackReady(side){const a=statusState();if(hasStatus(side,'stun')||hasStatus(side,'freeze')){a.clock[side]=0;return false;}a.clock[side]=Math.min(1.99,a.clock[side]+(hasStatus(side,'slow')?.7:1)*window.eldoria26AttackSpeed(side));if(a.clock[side]<1)return false;a.clock[side]-=1;return true;}
function tickStatuses(s,e){const a=statusState();a.immunity=Math.max(0,a.immunity-1);for(const side of ['hero','enemy'])for(const [k,v] of Object.entries(a[side])){const d=EFFECTS[k];if(v.left<=0){delete a[side][k];continue;}if(d[4]){const n=Math.max(1,Math.round(v.power*d[4]*v.stacks*(hasStatus(side,'expose')?1.2:1)));if(side==='hero')state.hp=Math.max(0,state.hp-n);else state.enemyHp=Math.max(0,state.enemyHp-n);statusText(side,d[1]+' '+(side==='hero'?'-':'')+n,d[2]);}v.left--; }if(!state.hp){defeat(s);return false;}if(!state.enemyHp){win();return false;}return true;}
