const POOLS=[['feet','hands','ring'],['weapon','armor','legs'],['head','accessory','ring'],['offhand','armor','hands'],['weapon','accessory','head','offhand','legs']];
const MATERIAL_RAR13=[[65,27,7,.9,.1],[55,30,12,2.7,.3],[47,32,16,4.5,.5],[38,34,20,7,1],[28,35,25,10,2]];const DROP_RATE=[.04,.055,.07,.09,.12];const MONSTER_RAR=[[83,14,2.7,.28,.02],[79,17,3.5,.46,.04],[74,20,5.2,.74,.06],[68,24,6.7,1.2,.1],[60,29,8.7,2.1,.2]];
