function dropSpec(mode,z=state.zone,id=state.enemy){const i=monsterIndex(z,id);return mode==='hunt'?{rate:DROP_RATE[i],slots:POOLS[i],odds:MONSTER_RAR[i]}:{rate:mode==='dungeon'?.60:.45,slots:Object.keys(SLOTS),odds:RAR_ODDS[mode]||RAR_ODDS.boss};}
function rollOdds(odds){let n=Math.random()*100;for(let i=0;i<odds.length;i++){n-=odds[i];if(n<0)return i;}return odds.length-1;}
addLoot=function(mode){const spec=dropSpec(mode);if(Math.random()>=spec.rate)return;if(state.inventory.length>=120){log('Inventário cheio: equipamento não recolhido.','bad');return;}const it=item(rand(spec.slots),state.zone,rollOdds(spec.odds));state.inventory.push(it);state.drops++;recordDrop(it);log('Item: '+it.name+' · '+RARITIES[it.rarity][0],'rare');};
