function atlasLoot(z,mode,id){const spec=dropSpec(mode,z,id),items=lootNames(z).filter(x=>spec.slots.includes(x.slot));return `<h3>Itens possíveis · ${pct(spec.rate*100)} de chance de equipamento</h3><p class="muted">Chance por vitória, sem considerar bolsa cheia. Cada item tem a probabilidade indicada, somadas todas as raridades.</p><div class="atlas-loot">${items.map(it=>`<div class="atlas-item" title="${it.name}"><img src="${itemIcon({...it,rarity:0})}"><span>${it.name}</span><b>${pct(spec.rate*100*it.weight*Object.keys(SLOTS).length/spec.slots.length)}</b></div>`).join('')}</div><table class="sheet-table"><thead><tr><th>Raridade</th><th>Se cair item</th><th>Por vitória</th></tr></thead><tbody>${spec.odds.map((v,i)=>`<tr><td style="color:${RARITIES[i][1]}">${RARITIES[i][0]}</td><td>${pct(v)}</td><td>${pct(v*spec.rate)}</td></tr>`).join('')}</tbody></table>${mode!=='hunt'?`<div class="loot-item09 relic09"><img src="${itemIcon({...RELICS[z],rarity:4})}"><div><b>${RELICS[z].name} · 0,25%</b><small>${RELICS[z].effect}</small></div></div>${mode==='dungeon'?runeLootPanel(z):'<p>Runas de status: exclusivas dos chefes finais de dungeon.</p>'}`:''}`;}
regionPanel=function(){const pics=thumbnails(),z=ZONES[atlasZone],id=z.enemy[atlasEnemy],e=ENEMIES[id];return `<div class="atlas10"><aside><div class="atlas-heading">MUNDO DE ELDORIA</div><button class="atlas-select" data-atlas-city><img src="${pics[ZONES.length]}"><span><b>Vespera</b><small>Zona segura</small></span></button>${ZONES.map((r,i)=>`<button data-atlas-zone="${i}" class="atlas-select ${atlasZone===i?'sel':''}"><img src="${pics[i]}"><span><b>${r.name}</b><small>Nv. ${r.level}+ · ${state.level<r.level?'Bloqueado':'Disponível'}</small></span></button>`).join('')}</aside><main><div class="atlas-hero" style="background-image:linear-gradient(0deg,#101218ee,transparent),url('${stageArt23['zone'+atlasZone]}')"><div><small>REGIÃO · ${z.type.toUpperCase()}</small><h2>${z.name}</h2><p>${ZDESC[atlasZone]}</p></div></div><div class="atlas-actions"><button class="primary" data-travel="${atlasZone}" ${state.level<z.level?'disabled':''}>Viajar · Nv. ${z.level}+</button><button class="secondary" data-atlas-mode="dungeon">Dungeon · Nv. ${Math.max(3,z.level+2)}+</button><button class="secondary" data-atlas-mode="boss">Boss · Nv. ${Math.max(5,z.level+4)}+</button></div><h3>Habitantes da região</h3><div class="atlas-monsters">${z.enemy.map((m,i)=>`<button data-atlas-enemy="${i}" class="${atlasMode==='hunt'&&atlasEnemy===i?'sel':''}" title="${ENEMIES[m].name}"><img src="${spriteThumb(m)}"><b>${ENEMIES[m].name}</b><small>${ENEMIES[m].hp} PV</small></button>`).join('')}</div><div class="atlas-detail"><h3>${atlasMode==='hunt'?e.name:atlasMode==='boss'?BOSSES[atlasZone]:'Chefe final da dungeon'}</h3>${atlasMode==='hunt'?`<p>${e.hp} PV · ${e.atk} ataque · ${e.xp} XP · ${e.gold} ouro · Status: ${EFFECTS[e.effect][0]}</p>`:`<p>3 andares de elites na dungeon · relíquia exclusiva do chefe.</p><button class="secondary" data-atlas-enter="${atlasMode}" ${allowed(atlasMode,atlasZone)&&state.level>=z.level?'':'disabled'}>Entrar ${atlasMode==='boss'?'no boss':'na dungeon'}</button>`}${atlasLoot(atlasZone,atlasMode,id)}</div><details><summary>Distribuição dos encaixes RNG</summary><table class="sheet-table"><tr><th>Raridade</th><th>0</th><th>1</th><th>2</th><th>3</th></tr>${SOCKET_ODDS.map((r,i)=>`<tr><td>${i===5?'Relíquia':RARITIES[i][0]}</td>${r.map(v=>`<td>${v}%</td>`).join('')}</tr>`).join('')}</table></details></main></div>`;};
