const hero10=hero;hero=function(c,x,y,scale=2,flash=false){if(!state.cls||state.cls==='war'){hero10(c,x,y,scale,flash);return;}paintActor(c,x,y,scale,state.cls,flash);};
function paintActor(c,x,y,s,kind,flash=false){c.save();c.translate(Math.round(x),Math.round(y));c.scale(s,s);const palette={ranger:['#263f32','#638b52','#a7a86c'],mage:['#332a4a','#635e9a','#a2a0db'],cleric:['#60553c','#c7b47e','#f0ddab'],forge:['#46302c','#8f5b3e','#b0a08b'],merchant:['#4d2940','#8e5668','#e0ad79'],train:['#393b40','#7d8793','#c8b7a2'],zones:['#344451','#718d9c','#d7cdb1'],sub:['#462e4f','#92709b','#d6b9cd']}[kind]||['#403830','#8e7457','#c6b691'];const [d,m,l]=palette,r=(a,b,w,h,col)=>rect(c,a,b,w,h,flash?'#eee5cd':col);r(-12,16,24,3,'#15151a');r(-9,-7,18,23,d);r(-6,-5,12,19,m);r(-8,8,16,7,kind==='ranger'?d:m);r(-7,15,6,3,'#2d272a');r(2,15,6,3,'#2d272a');r(-8,-18,16,13,d);r(-5,-20,10,4,m);r(-5,-13,10,8,'#c7a27e');r(-4,-11,2,2,'#211d28');r(3,-11,2,2,'#211d28');r(-9,-17,5,10,m);r(5,-17,5,10,m);r(-9,1,18,3,l);r(-12,-5,5,13,m);r(8,-5,5,12,m);if(kind==='ranger'){r(11,-13,3,26,'#ad8857');r(8,-15,5,3,'#ad8857');r(8,12,5,3,'#ad8857');r(8,-12,1,24,'#e3cba0');}else if(kind==='mage'||kind==='cleric'||kind==='sub'){r(12,-20,3,37,'#987955');r(9,-24,9,8,l);r(11,-22,5,4,'#f4e5ce');r(-5,-3,10,2,l);}else{r(12,-7,4,18,'#9d7956');r(8,-11,12,6,l);}c.restore();}
