const creature10=creature;creature=function(c,id,x,y,s=1,flash=false){if(!bestiaryAdd.some(a=>a[0]===id)){creature10(c,id,x,y,s,flash);return;}c.save();c.translate(Math.round(x),Math.round(y));c.scale(s,s);const r=(a,b,w,h,col)=>rect(c,a,b,w,h,flash?'#eadfce':col);r(-18,11,36,4,'#1b1a21');if(['spider','scorpion'].includes(id)){const col=id==='spider'?'#6f5b82':'#80654a';for(let i=0;i<4;i++){r(-20,-9+i*5,14,2,col);r(6,-9+i*5,14,2,col);r(-20,-7+i*5,3,4,col);r(17,-7+i*5,3,4,col);}r(-10,-11,20,18,col);r(-6,-14,12,7,'#403643');r(-5,-6,3,3,'#e2a758');r(2,-6,3,3,'#e2a758');if(id==='scorpion'){r(5,-21,4,12,'#9b794e');r(2,-23,7,4,'#dd9751');}}else if(id==='boar'){r(-15,-8,28,17,'#685346');r(-19,-3,13,10,'#9b7561');r(-17,4,3,6,'#ded0b0');r(-11,-12,5,8,'#9c6156');r(-10,-5,3,2,'#e58b63');r(-10,7,5,7,'#382d2a');r(8,7,5,7,'#382d2a');}else if(['wraith','cultist'].includes(id)){const col=id==='wraith'?'#676d93':'#753b60';r(-9,-17,18,10,col);r(-6,-11,12,7,'#22202a');r(-5,-10,3,2,'#c5b5ef');r(2,-10,3,2,'#c5b5ef');r(-12,-5,24,13,col);r(-15,7,30,4,col);r(-10,11,5,4,col);r(4,11,5,4,col);}else{const col={ghoul:'#7c8c67',knight:'#646a82',imp:'#a34e43',elemental:'#6d4440'}[id];r(-9,-18,18,12,col);r(-5,-13,3,3,'#ffb16b');r(2,-13,3,3,'#ffb16b');r(-12,-6,24,16,col);r(-16,-4,5,13,col);r(11,-4,5,13,col);r(-9,9,7,6,col);r(2,9,7,6,col);if(id==='imp'){r(-12,-23,5,10,'#c49a72');r(7,-23,5,10,'#c49a72');}if(id==='knight'){r(14,-19,3,28,'#c1bcc8');r(-19,-4,8,12,'#b09a72');}if(id==='elemental'){r(-3,-5,4,12,'#f19c51');r(-8,2,15,3,'#f19c51');}}c.restore();};
function drawStatusEffects(now){if(!state.active||state.mode==='train'||state.mode==='city')return;const a=statusState();for(const side of ['hero','enemy']){const p=side==='hero'?pos:enemyPoint(now);const es=Object.entries(a[side]).filter(([k,v])=>v.left>0);es.forEach(([k,v],i)=>{const d=EFFECTS[k];ctx.save();ctx.font='10px monospace';ctx.fillStyle=d[2];ctx.fillText(d[1],p.x-10*es.length+i*20,p.y+28);ctx.globalAlpha=.5;for(let j=0;j<5;j++){const angle=now/340+j*1.26;rect(ctx,p.x+Math.cos(angle)*19,p.y+Math.sin(angle)*12,2,2,d[2]);}ctx.restore();});}if(fx&&now-fx.t<400){const p=enemyPoint(now);ctx.save();ctx.globalAlpha=(1-(now-fx.t)/400)*.7;for(let i=0;i<9;i++){const t=(now-fx.t)/30;rect(ctx,p.x+Math.cos(i*2.4)*t,p.y+Math.sin(i*2.4)*t,2,2,'#91353c');}ctx.restore();}}
function initExpansion(){const el=$('content-zones');el.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.atlasCity!==undefined){switchActivity('city');closeWindow('zones');return;}if(d.atlasZone!==undefined){atlasZone=+d.atlasZone;atlasEnemy=0;atlasMode='hunt';}else if(d.atlasEnemy!==undefined){atlasEnemy=+d.atlasEnemy;atlasMode='hunt';}else if(d.atlasMode){atlasMode=d.atlasMode;}else if(d.atlasEnter){switchActivity(d.atlasEnter,atlasZone);closeWindow('zones');return;}else return;$('zones').innerHTML=regionPanel();});WINDOW_DEFS.zones[2]=1000;WINDOW_DEFS.zones[3]=750;const el2=document.createElement('div');el2.id='statusHUD10';$('battleInfo').append(el2);}
const refresh10=refreshSkillBar;refreshSkillBar=function(){refresh10();const el=$('statusHUD10');if(!el)return;const a=statusState(),h=['hero','enemy'].map(side=>`<div><small>${side==='hero'?'Você':'Alvo'}</small> ${Object.entries(a[side]).filter(([k,v])=>v.left>0).map(([k,v])=>`<span style="color:${EFFECTS[k][2]}" title="${EFFECTS[k][0]} · ${EFFECT_DESC[k]}">${EFFECTS[k][1]} ${v.left}s${v.stacks>1?' ×'+v.stacks:''}</span>`).join('')||'<small>—</small>'}</div>`).join('');if(el.innerHTML!==h)el.innerHTML=h;};


// Dungeon Codex and status runes, v0.9. Rune stock is separate from equipment inventory.
const RUNE_RATE=.11,RUNE_ODDS=[66,24,8.5,1.3,.2],RUNE_PROC=[5,8,12,16,22],RUNE_PRICE=[40,100,260,750,2400];
const RUNE_POOLS=[['bleed','slow','poison'],['stun','expose','freeze'],['burn','shock','freeze']];
for(const effect of Object.keys(EFFECTS))for(let rarity=0;rarity<5;rarity++){
 const d=EFFECTS[effect];RUNES['status_'+effect+'_'+rarity]={name:'Runa de '+d[0]+' · '+RARITIES[rarity][0],mods:{},price:RUNE_PRICE[rarity],rarity,effect,proc:RUNE_PROC[rarity],desc:RUNE_PROC[rarity]+'% por golpe para aplicar '+d[0]+' por '+d[3]+' s. '+EFFECT_DESC[effect]};
}
function runeIcon(k){const r=RUNES[k],color=r.effect?EFFECTS[r.effect][2]:'#bda272';const marks={bleed:'M16 6L9 19v5l4 3h6l4-3v-5z',stun:'M16 6v20M6 16h20M9 9l14 14M23 9L9 23',slow:'M10 7h12M10 25h12M10 7v5l6 4-6 4v5M22 7v5l-6 4 6 4v5',expose:'M16 5l10 11-10 11L6 16zM16 10v12',poison:'M9 9h14v12h-4v5h-6v-5H9zM12 14h2m4 0h2',burn:'M17 5l5 10-3 3 5 2v4l-5 4H11l-4-5 3-10 4 5z',freeze:'M16 5v22M6 10l20 12M6 22l20-12',shock:'M18 5L8 18h9l-3 10 12-15h-9z'};return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><path d="M7 3h18l5 8-2 15-8 4H10L3 22 4 9z" fill="#272630" stroke="${r.effect?RARITIES[r.rarity][1]:'#8c785d'}" stroke-width="2"/><path d="${marks[r.effect]||marks.expose}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round"/></svg>`);}
function procRunes(dmg){const groups={};for(const id of Object.values(state.equipment)){const it=state.inventory.find(x=>x.id===id);for(const k of it?.runes||[]){const r=RUNES[k];if(r?.effect)groups[r.effect]=(groups[r.effect]||1)*(1-r.proc/100);}}for(const [effect,noProc] of Object.entries(groups))if(Math.random()<1-noProc)applyStatus('enemy',effect,dmg);}
const reward11=bossReward;bossReward=function(){if(state.mode==='dungeon'&&state.wave===4&&Math.random()<RUNE_RATE){const rarity=rollOdds(RUNE_ODDS),key=window.eldoria30RuneDrop?window.eldoria30RuneDrop(state.zone,rarity):'status_'+rand(RUNE_POOLS[state.zone])+'_'+rarity,r=RUNES[key];state.runeStock[key]=(state.runeStock[key]||0)+1;const a=state.analyzer;if(a){a.runeDrops=a.runeDrops||{};a.runeDrops[key]=(a.runeDrops[key]||0)+1;a.itemValue+=r.price;}log('RUNA: '+r.name,'rare');}if(Math.random()>=.0025||state.inventory.length>=120)return;const r=RELICS[state.zone],it=rebuildItem({id:state.nextId++,name:r.name,slot:r.slot,rarity:4,tier:state.zone,quality:3,baseMods:relicMods10(r),mods:relicMods10(r),upgrade:0,runes:[],relic:state.zone});state.inventory.push(it);state.drops++;recordDrop(it);log('RELÍQUIA EXCLUSIVA: '+it.name+'!','rare');};
function runeLootPanel(z){return `<h3>Runas exclusivas · ${pct(RUNE_RATE*100)} por chefe final</h3><p class="muted">Uma rolagem independente de equipamento e relíquia. Tipo sorteado igualmente entre as três runas da dungeon. Cada raridade aumenta a chance de ativação por golpe; duplicatas combinam probabilidades, não multiplicam aplicações no mesmo golpe.</p><div class="atlas-loot">${RUNE_POOLS[z].map(e=>`<div class="atlas-item"><img src="${runeIcon('status_'+e+'_0')}"><span>${EFFECTS[e][0]}<small>${EFFECT_DESC[e]} · ${EFFECTS[e][3]} s</small></span><b>${pct(RUNE_RATE*100/RUNE_POOLS[z].length)}</b></div>`).join('')}</div><table class="sheet-table"><thead><tr><th>Raridade</th><th>Se cair runa</th><th>Por chefe (qualquer tipo)</th><th>Por chefe (tipo específico)</th><th>Ativação</th><th>Venda</th></tr></thead><tbody>${RUNE_ODDS.map((v,i)=>`<tr><td style="color:${RARITIES[i][1]}">${RARITIES[i][0]}</td><td>${pct(v)}</td><td>${pct(v*RUNE_RATE)}</td><td>${pct(v*RUNE_RATE/RUNE_POOLS[z].length)}</td><td>${RUNE_PROC[i]}%</td><td>${RUNE_PRICE[i]} ◈</td></tr>`).join('')}</tbody></table>`;}
